    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    target_y = 11.7
    if pos.y < target_y:
        force_mag = 42.0
        # Apply horizontal force based on position relative to pivot
        if (pos.x < 10.0 and vx > 0) or (pos.x > 10.0 and vx < 0):
            # Push towards the pivot
            sandbox.apply_force_to_seat(force_mag if vx > 0 else -force_mag, force_mag)
        elif (pos.x < 10.0 and vx < 0) or (pos.x > 10.0 and vx > 0):
            # Push away from the pivot
            sandbox.apply_force_to_seat(-force_mag if pos.x < 10.0 else force_mag, force_mag)
    else:
        # Apply a force to slow the swing down at the apex
        sandbox.apply_force_to_seat(-vx * 10.0, 0)
